AssistantMessageToolRequest(name='create', tool_call_id='tooluse_L31w4qFGQ3vxWldC2KRKK3', arguments={'file_text': '/* === Reset & Base === */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #f8f8f6;
  --color-surface: #ffffff;
  --color-surface-alt: #f2f0ed;
  --color-border: #e0ddd8;
  --color-text: #1a1a18;
  --color-text-secondary: #5c5c56;
  --color-accent: #2d6a4f;
  --color-accent-hover: #1b4332;
  --color-accent-fg: #ffffff;
  --color-deal: #b5451b;
  --color-deal-bg: #fff3ef;
  --color-deal-border: #f4c7b7;
  --color-focus: #2563eb;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-card: 0 2px 8px rgba(0,0,0,.07), 0 0 0 1px rgba(0,0,0,.04);
  --shadow-hover: 0 6px 24px rgba(0,0,0,.10), 0 0 0 1px rgba(0,0,0,.06);
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --transition: 180ms ease;
  --max-w: 1280px;
}

html { font-size: 16px; }
body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100vh;
}

img { display: block; max-width: 100%; height: auto; }
ul { list-style: none; }
a { color: inherit; text-decoration: none; }
button { font: inherit; cursor: pointer; border: none; background: none; }

/* === Focus === */
:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

/* === Skip link === */
.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--color-focus);
  color: #fff;
  padding: .6rem 1.2rem;
  font-weight: 600;
  z-index: 1000;
  border-radius: 0 0 var(--radius-sm) 0;
}
.skip-link:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* === Layout utils === */
.container { max-width: var(--max-w); margin-inline: auto; padding-inline: 1.25rem; }
.section-header { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 1.5rem; flex-wrap: wrap; }
.section-header h2 { font-size: clamp(1.3rem, 2.5vw, 1.75rem); font-weight: 700; letter-spacing: -.02em; }
.view-all { font-size: .875rem; font-weight: 600; color: var(--color-accent); text-decoration: underline; text-underline-offset: 3px; }
.view-all:hover { color: var(--color-accent-hover); }

/* === Header === */
.site-header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
  position: sticky; top: 0; z-index: 100;
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding-block: .875rem;
}

/* Logo */
.site-logo { display: flex; align-items: center; gap: .5rem; text-decoration: none; flex-shrink: 0; }
.site-logo svg { width: 36px; height: 36px; }
.site-logo-text { font-size: 1.2rem; font-weight: 800; letter-spacing: -.04em; color: var(--color-text); }
.site-logo-text span { color: var(--color-accent); }

/* Primary nav */
.primary-nav { display: flex; justify-content: center; }
.primary-nav ul { display: flex; gap: .25rem; }
.primary-nav a {
  display: block;
  padding: .45rem .8rem;
  font-size: .9rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: background var(--transition), color var(--transition);
}
.primary-nav a:hover { background: var(--color-surface-alt); }
.primary-nav a[aria-current="page"] {
  color: var(--color-accent);
  background: #e8f5ee;
  font-weight: 600;
}

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; }

.search-form { display: flex; align-items: center; gap: .25rem; }
.search-input {
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: .45rem .75rem;
  font-size: .875rem;
  background: var(--color-bg);
  width: 180px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.search-input:focus { outline: none; border-color: var(--color-accent); box-shadow: 0 0 0 3px rgba(45,106,79,.2); }
.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
  position: relative;
}
.icon-btn:hover { background: var(--color-surface-alt); }
.icon-btn svg { width: 20px; height: 20px; flex-shrink: 0; }
.cart-badge {
  position: absolute; top: 4px; right: 4px;
  background: var(--color-deal); color: #fff;
  font-size: .65rem; font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 99px; display: flex; align-items: center; justify-content: center;
  line-height: 1;
  pointer-events: none;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* === Hero === */
.hero {
  background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 55%, #40916c 100%);
  color: #fff;
  padding: clamp(3rem, 8vw, 5.5rem) 0;
  overflow: hidden;
  position: relative;
}
.hero::after {
  content: '';
  position: absolute; inset: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
  pointer-events: none;
}
.hero-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center; position: relative; z-index: 1; }
.hero-eyebrow { font-size: .8rem; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; opacity: .75; margin-bottom: .75rem; }
.hero h1 { font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; letter-spacing: -.04em; line-height: 1.1; margin-bottom: 1.25rem; }
.hero-sub { font-size: 1.05rem; opacity: .85; max-width: 40ch; margin-bottom: 2rem; }
.hero-ctas { display: flex; gap: .75rem; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: .5rem;
  background: #fff; color: var(--color-accent);
  padding: .7rem 1.4rem;
  border-radius: var(--radius-md);
  font-weight: 700; font-size: .95rem;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  box-shadow: 0 2px 12px rgba(0,0,0,.15);
}
.btn-primary:hover { background: #f0f9f4; transform: translateY(-1px); box-shadow: 0 4px 20px rgba(0,0,0,.2); }
.btn-secondary {
  display: inline-flex; align-items: center; gap: .5rem;
  background: rgba(255,255,255,.15); color: #fff;
  padding: .7rem 1.4rem;
  border-radius: var(--radius-md);
  font-weight: 600; font-size: .95rem;
  border: 1.5px solid rgba(255,255,255,.35);
  transition: background var(--transition), transform var(--transition);
  backdrop-filter: blur(4px);
}
.btn-secondary:hover { background: rgba(255,255,255,.25); transform: translateY(-1px); }

.hero-image-wrap {
  display: flex; justify-content: flex-end;
}
.hero-product-card {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  width: 100%; max-width: 360px;
  backdrop-filter: blur(8px);
  display: flex; flex-direction: column; gap: 1rem;
}
.hero-product-image {
  width: 100%; aspect-ratio: 4/3;
  border-radius: var(--radius-md);
  object-fit: cover;
  background: linear-gradient(135deg, #52b788, #74c69d);
  display: flex; align-items: center; justify-content: center;
  font-size: 5rem;
}
.hero-product-info { color: #fff; }
.hero-product-label { font-size: .75rem; opacity: .7; text-transform: uppercase; letter-spacing: .08em; margin-bottom: .25rem; }
.hero-product-name { font-size: 1.15rem; font-weight: 700; margin-bottom: .25rem; }
.hero-product-price { font-size: 1.5rem; font-weight: 800; }
.hero-product-original { font-size: .9rem; opacity: .65; text-decoration: line-through; margin-left: .4rem; font-weight: 400; }

/* === Promo bar === */
.promo-bar {
  background: var(--color-text);
  color: #fff;
  font-size: .85rem;
  font-weight: 500;
  text-align: center;
  padding: .6rem 1rem;
  display: flex; align-items: center; justify-content: center; gap: .5rem;
}
.promo-bar a { color: #81d4a4; text-decoration: underline; text-underline-offset: 2px; }

/* === Sections === */
section { padding: clamp(2.5rem, 5vw, 4rem) 0; }
section:nth-of-type(even) { background: var(--color-surface); }

/* === Category pills === */
.category-grid { display: flex; gap: .75rem; flex-wrap: wrap; }
.category-pill {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .55rem 1.1rem;
  border: 1.5px solid var(--color-border);
  border-radius: 99px;
  font-size: .875rem; font-weight: 500;
  background: var(--color-surface);
  transition: background var(--transition), border-color var(--transition), transform var(--transition);
}
.category-pill:hover { background: var(--color-surface-alt); border-color: var(--color-accent); transform: translateY(-1px); }
.category-pill-icon { font-size: 1.1rem; }

/* === Product grid === */
.product-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 1.25rem; }

.product-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition), transform var(--transition);
  display: flex; flex-direction: column;
}
.product-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }

.product-card-image-wrap {
  position: relative;
  aspect-ratio: 1/1;
  background: var(--color-surface-alt);
  overflow: hidden;
}
.product-card-image-wrap .product-emoji {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
}
.badge {
  position: absolute; top: .75rem; left: .75rem;
  font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .06em;
  padding: .25rem .55rem;
  border-radius: 99px;
  line-height: 1;
}
.badge-new { background: var(--color-text); color: #fff; }
.badge-deal { background: var(--color-deal); color: #fff; }
.badge-trending { background: #7c3aed; color: #fff; }

.wishlist-btn {
  position: absolute; top: .6rem; right: .6rem;
  width: 32px; height: 32px;
  background: rgba(255,255,255,.9);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  transition: background var(--transition), transform var(--transition);
  box-shadow: 0 1px 4px rgba(0,0,0,.12);
}
.wishlist-btn:hover { background: #fff; transform: scale(1.1); }
.wishlist-btn svg { width: 16px; height: 16px; }
.wishlist-btn[aria-pressed="true"] svg { fill: #e53e3e; stroke: #e53e3e; }

.product-card-body { padding: 1rem; flex: 1; display: flex; flex-direction: column; gap: .35rem; }
.product-brand { font-size: .72rem; font-weight: 600; text-transform: uppercase; letter-spacing: .07em; color: var(--color-text-secondary); }
.product-name { font-size: .95rem; font-weight: 600; line-height: 1.35; }
.product-name a { text-decoration: none; }
.product-name a:hover { color: var(--color-accent); text-decoration: underline; text-underline-offset: 2px; }
.product-rating { display: flex; align-items: center; gap: .35rem; font-size: .8rem; color: var(--color-text-secondary); }
.stars { color: #f59e0b; letter-spacing: -.05em; }
.product-price-row { display: flex; align-items: center; gap: .5rem; margin-top: auto; padding-top: .5rem; }
.price-current { font-size: 1.05rem; font-weight: 700; }
.price-original { font-size: .85rem; color: var(--color-text-secondary); text-decoration: line-through; }
.price-save { font-size: .75rem; font-weight: 600; color: var(--color-deal); }

.product-card-footer { padding: .75rem 1rem; border-top: 1px solid var(--color-border); }
.add-to-cart {
  width: 100%;
  padding: .55rem 1rem;
  background: var(--color-accent);
  color: var(--color-accent-fg);
  border-radius: var(--radius-sm);
  font-size: .875rem; font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  display: flex; align-items: center; justify-content: center; gap: .4rem;
}
.add-to-cart:hover { background: var(--color-accent-hover); transform: translateY(-1px); }
.add-to-cart:active { transform: translateY(0); }

/* === Deals section === */
.deals-section { background: var(--color-deal-bg); }
.deals-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 1.25rem; }
.deal-card {
  background: var(--color-surface);
  border: 1.5px solid var(--color-deal-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: 0 2px 8px rgba(181,69,27,.06);
  transition: box-shadow var(--transition), transform var(--transition);
}
.deal-card:hover { box-shadow: 0 6px 24px rgba(181,69,27,.12); transform: translateY(-2px); }
.deal-card-top { display: flex; align-items: center; gap: 1rem; padding: 1rem; flex: 1; }
.deal-card-emoji { font-size: 3.5rem; line-height: 1; flex-shrink: 0; }
.deal-card-info { flex: 1; min-width: 0; }
.deal-card-tag { font-size: .7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--color-deal); margin-bottom: .25rem; }
.deal-card-name { font-size: .95rem; font-weight: 600; margin-bottom: .3rem; }
.deal-card-name a:hover { color: var(--color-accent); text-decoration: underline; text-underline-offset: 2px; }
.deal-price-row { display: flex; align-items: baseline; gap: .4rem; }
.deal-price { font-size: 1.15rem; font-weight: 800; color: var(--color-deal); }
.deal-original { font-size: .8rem; color: var(--color-text-secondary); text-decoration: line-through; }
.deal-card-footer { padding: .75rem 1rem; border-top: 1px solid var(--color-deal-border); display: flex; align-items: center; justify-content: space-between; gap: .75rem; }
.deal-timer { font-size: .78rem; color: var(--color-text-secondary); display: flex; align-items: center; gap: .3rem; }
.deal-timer svg { width: 14px; height: 14px; flex-shrink: 0; }
.deal-timer strong { color: var(--color-deal); font-weight: 700; }
.deal-add-btn {
  padding: .45rem .9rem;
  background: var(--color-deal);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .8rem; font-weight: 600;
  transition: background var(--transition), transform var(--transition);
  white-space: nowrap;
}
.deal-add-btn:hover { background: #8b3013; transform: translateY(-1px); }

/* === Editorial section === */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}
.editorial-card {
  background: var(--color-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: flex; flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-hover); transform: translateY(-2px); }
.editorial-card--featured { grid-row: span 2; }
.editorial-card-image {
  width: 100%; aspect-ratio: 16/9;
  background: linear-gradient(135deg, var(--c1, #2d6a4f), var(--c2, #52b788));
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
  flex-shrink: 0;
}
.editorial-card--featured .editorial-card-image { aspect-ratio: 4/5; }
.editorial-card-body { padding: 1.25rem; flex: 1; display: flex; flex-direction: column; gap: .5rem; }
.editorial-tag { font-size: .72rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--color-accent); }
.editorial-title { font-size: 1.05rem; font-weight: 700; line-height: 1.3; }
.editorial-card--featured .editorial-title { font-size: clamp(1.15rem, 2.5vw, 1.4rem); }
.editorial-title a:hover { color: var(--color-accent); text-decoration: underline; text-underline-offset: 3px; }
.editorial-excerpt { font-size: .875rem; color: var(--color-text-secondary); line-height: 1.55; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.editorial-meta { margin-top: auto; display: flex; align-items: center; gap: .5rem; font-size: .78rem; color: var(--color-text-secondary); }
.editorial-meta-dot { opacity: .4; }

/* === Brands strip === */
.brands-section { background: var(--color-surface); padding-block: 2.5rem; }
.brands-label { font-size: .78rem; font-weight: 600; text-transform: uppercase; letter-spacing: .1em; color: var(--color-text-secondary); text-align: center; margin-bottom: 1.25rem; }
.brands-strip { display: flex; align-items: center; justify-content: center; gap: 2.5rem; flex-wrap: wrap; }
.brand-item { font-size: 1.05rem; font-weight: 800; letter-spacing: -.03em; color: var(--color-border); transition: color var(--transition); }
.brand-item:hover { color: var(--color-text-secondary); }

/* === Newsletter === */
.newsletter-section {
  background: linear-gradient(135deg, #1b4332 0%, #2d6a4f 100%);
  color: #fff;
  padding: clamp(3rem, 6vw, 5rem) 0;
}
.newsletter-inner { max-width: 560px; margin-inline: auto; text-align: center; }
.newsletter-inner h2 { font-size: clamp(1.5rem, 3vw, 2.2rem); font-weight: 800; letter-spacing: -.03em; margin-bottom: .75rem; }
.newsletter-inner p { opacity: .8; margin-bottom: 2rem; }
.newsletter-form { display: flex; gap: .5rem; }
.newsletter-input {
  flex: 1;
  padding: .7rem 1rem;
  border: none;
  border-radius: var(--radius-sm);
  font-size: .95rem;
  min-width: 0;
}
.newsletter-input:focus { outline: 3px solid rgba(255,255,255,.6); outline-offset: 2px; }
.newsletter-btn {
  padding: .7rem 1.4rem;
  background: var(--color-text);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 700; font-size: .95rem;
  white-space: nowrap;
  transition: background var(--transition), transform var(--transition);
}
.newsletter-btn:hover { background: #333; transform: translateY(-1px); }
.newsletter-note { margin-top: .75rem; font-size: .78rem; opacity: .6; }

/* === Footer === */
.site-footer { background: var(--color-text); color: rgba(255,255,255,.8); padding: 3rem 0 1.5rem; }
.footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 2.5rem; margin-bottom: 2.5rem; }
.footer-brand { display: flex; flex-direction: column; gap: .75rem; }
.footer-logo { display: flex; align-items: center; gap: .5rem; text-decoration: none; color: #fff; }
.footer-logo svg { width: 30px; height: 30px; }
.footer-logo-text { font-size: 1.1rem; font-weight: 800; letter-spacing: -.04em; }
.footer-logo-text span { color: #81d4a4; }
.footer-tagline { font-size: .875rem; line-height: 1.55; max-width: 28ch; }
.footer-social { display: flex; gap: .5rem; }
.footer-social a {
  display: flex; align-items: center; justify-content: center;
  width: 36px; height: 36px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.08);
  color: rgba(255,255,255,.7);
  transition: background var(--transition), color var(--transition);
}
.footer-social a:hover { background: rgba(255,255,255,.16); color: #fff; }
.footer-social svg { width: 16px; height: 16px; }
.footer-col h3 { font-size: .8rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: rgba(255,255,255,.5); margin-bottom: .85rem; }
.footer-links { display: flex; flex-direction: column; gap: .5rem; }
.footer-links a { font-size: .875rem; color: rgba(255,255,255,.7); transition: color var(--transition); }
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 1.25rem;
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  font-size: .78rem; color: rgba(255,255,255,.45);
  flex-wrap: wrap;
}
.footer-bottom-links { display: flex; gap: 1.25rem; }
.footer-bottom-links a { color: rgba(255,255,255,.45); transition: color var(--transition); }
.footer-bottom-links a:hover { color: rgba(255,255,255,.8); }

/* === Cart notification === */
.cart-notification {
  position: fixed; bottom: 1.5rem; right: 1.5rem;
  background: var(--color-text);
  color: #fff;
  padding: .85rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: 0 8px 30px rgba(0,0,0,.2);
  z-index: 500;
  transform: translateY(8px);
  opacity: 0;
  transition: opacity 220ms ease, transform 220ms ease;
  pointer-events: none;
  max-width: 320px;
  display: flex; align-items: center; gap: .6rem;
}
.cart-notification.visible { opacity: 1; transform: translateY(0); pointer-events: auto; }
.cart-notification svg { width: 18px; height: 18px; flex-shrink: 0; color: #81d4a4; }

/* === Reduced motion === */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

/* === Forced colors === */
@media (forced-colors: active) {
  .btn-primary, .btn-secondary, .add-to-cart, .deal-add-btn, .newsletter-btn {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .badge { border: 1px solid ButtonText; }
}

/* === Responsive === */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-sub { margin-inline: auto; }
  .hero-ctas { justify-content: center; }
  .hero-image-wrap { justify-content: center; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto auto; grid-template-rows: auto auto; }
  .primary-nav { display: none; grid-column: 1 / -1; padding-bottom: .5rem; }
  .primary-nav.open { display: flex; }
  .primary-nav ul { flex-direction: column; gap: .15rem; width: 100%; }
  .primary-nav a { display: block; }
  .menu-toggle { display: flex; }
  .search-input { width: 140px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-row: span 1; }
  .editorial-card--featured .editorial-card-image { aspect-ratio: 16/9; }
}

@media (max-width: 540px) {
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-product-card { max-width: 100%; }
  .search-form { display: none; }
}

/* === Min 320px reflow guard === */
@media (max-width: 360px) {
  .header-actions { gap: .25rem; }
  .deals-grid, .product-grid { grid-template-columns: 1fr; }
}
