  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  font-size: .78rem; color: rgba(255,255,255,.45);
  flex-wrap: wrap;
}
.footer-bottom-links { display: flex; gap: 1.25rem; }
.footer-bottom-links a { color: rgba(255,255,255,.45); transition: color var(--transition); }
.footer-bottom-links a:hover { color: rgba(255,255,255,.8); }

/* === Cart notification === */
.cart-notification {
  position: fixed; bottom: 1.5rem; right: 1.5rem;
  background: var(--color-text);
  color: #fff;
  padding: .85rem 1.25rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  box-shadow: 0 8px 30px rgba(0,0,0,.2);
  z-index: 500;
  transform: translateY(8px);
  opacity: 0;
  transition: opacity 220ms ease, transform 220ms ease;
  pointer-events: none;
  max-width: 320px;
  display: flex; align-items: center; gap: .6rem;
}
.cart-notification.visible { opacity: 1; transform: translateY(0); pointer-events: auto; }
.cart-notification svg { width: 18px; height: 18px; flex-shrink: 0; color: #81d4a4; }

