}

/* === Forced colors === */
@media (forced-colors: active) {
  .btn-primary, .btn-secondary, .add-to-cart, .deal-add-btn, .newsletter-btn {
    border: 2px solid ButtonText;
    forced-color-adjust: none;
  }
  .badge { border: 1px solid ButtonText; }
}

/* === Responsive === */
@media (max-width: 1024px) {
  .hero-inner { grid-template-columns: 1fr; text-align: center; }
  .hero-sub { margin-inline: auto; }
  .hero-ctas { justify-content: center; }
  .hero-image-wrap { justify-content: center; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 768px) {
  .header-inner { grid-template-columns: auto auto; grid-template-rows: auto auto; }
  .primary-nav { display: none; grid-column: 1 / -1; padding-bottom: .5rem; }
  .primary-nav.open { display: flex; }
  .primary-nav ul { flex-direction: column; gap: .15rem; width: 100%; }
  .primary-nav a { display: block; }
  .menu-toggle { display: flex; }
  .search-input { width: 140px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--featured { grid-row: span 1; }
  .editorial-card--featured .editorial-card-image { aspect-ratio: 16/9; }
}

@media (max-width: 540px) {
  .newsletter-form { flex-direction: column; }
  .footer-grid { grid-template-columns: 1fr; }
  .hero-product-card { max-width: 100%; }
  .search-form { display: none; }
}

/* === Min 320px reflow guard === */
@media (max-width: 360px) {
  .header-actions { gap: .25rem; }
  .deals-grid, .product-grid { grid-template-columns: 1fr; }
}

